 const metricLabel=k=>({sample_count:'Sammenlignelige observationer',price:'Kurs',quote_age_s:'Kursalder (sek.)',return_1_pct:'Afkast 1 interval (%)',return_3_pct:'Afkast 3 intervaller (%)',return_window_pct:'Kursændring i valgt tidsvindue (%)',reference_gain_pct:'Ændring fra ordinært luk (%)',news_reaction_pct:'Ændring siden nyheden (%)',catalyst_age_minutes:'Nyhedens alder (min.)',ordinary_share:'Almindelig aktie ifølge Pluto',pluto_tradable:'Handelsbarhed ifølge Pluto',relative_volume:'Relativ intervalvolumen',spread_pct:'Spread (%)',spread:'Spread',rsi:'RSI',atr:'ATR',macd:'MACD',macd_signal:'MACD signallinje',macd_histogram:'MACD histogram',breakout:'Kursbrud op',breakdown:'Kursbrud ned',trend_up:'Stigende trend',volatility_pct:'Volatilitet (%)'}[k]||k.replaceAll('_',' '));
